import json,subprocess,sys
seq=json.loads(subprocess.check_output(['build/dump',sys.argv[1]]))
s=[n['Type'] for n in seq]+['$']
for i,n in enumerate(seq): print(i,n['Type'],n['Size'],str(n['Line'])+':'+str(n['Col']))
# Direct exhaustive maximal repeats, adequate for the tiny probes.
D={}
for i in range(len(s)):
 for j in range(i+1,len(s)):
  key=tuple(s[i:j]); D.setdefault(key,[]).append(i)
print('MAXIMAL REPEATS')
for key,occ in D.items():
 if len(occ)<2: continue
 if len({s[i-1] if i else '^' for i in occ})==1:continue
 if len({s[i+len(key)] for i in occ})==1:continue
 print('LEN',len(key),'SEQ',key,'OCC',occ)
 for t in [1,2,3,4,5,15]:
  units=[];i=occ[0];end=i+len(key)
  while i<end:
   n=seq[i]
   if n['Size']>=t and i+n['Size']<=end:
    units.append((i-occ[0],n['Type'],n['Size'],str(n['Line'])+':'+str(n['Col'])))
    i+=n['Size']
   else:i+=1
  if units:print(' t',t,units)
