func codeFragment(f fragment) string {
	src := f.source.data
	lineStart := bytes.LastIndexByte(src[:f.begin], '\n') + 1
	prefix := append([]byte(nil), src[lineStart:f.begin]...)
	indent := len(prefix)
	for i, b := range prefix {
		if b != '\t' {
			prefix[i] = ' '
			indent = 0
		}
	}
	code := append(prefix, src[f.begin:f.end]...)
	if indent != 0 {
		lines := bytes.Split(code, []byte{'\n'})
		for i, line := range lines {
