cat > syntax.go <<'EOF'
package main

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"reflect"
	"sort"
)

// A node's size includes the node and its preorder descendants. Positions are
// byte offsets in the original file, not positions in a reformatted source.
type syntaxNode struct {
	kind, size int
	begin, end int
	source     *sourceFile
}

type sourceFile struct {
	name  string
	data  []byte
	lines []int
}

func (s *sourceFile) lineAt(offset int) int {
	return sort.Search(len(s.lines), func(i int) bool { return s.lines[i] > offset })
}

var nodeKinds = map[string]int{
	"File": 1, "ArrayType": 2, "AssignStmt": 3, "BasicLit": 4,
	"BinaryExpr": 5, "BlockStmt": 6, "BranchStmt": 7, "CallExpr": 8,
	"CaseClause": 9, "ChanType": 10, "CommClause": 11, "CompositeLit": 12,
	"DeclStmt": 13, "DeferStmt": 14, "Ellipsis": 15, "EmptyStmt": 16,
	"ExprStmt": 17, "Field": 18, "FieldList": 19, "ForStmt": 20,
	"FuncDecl": 21, "FuncLit": 22, "FuncType": 23, "GenDecl": 24,
	"GoStmt": 25, "Ident": 26, "IfStmt": 27, "IncDecStmt": 28,
	"IndexExpr": 29, "InterfaceType": 30, "KeyValueExpr": 31,
	"LabeledStmt": 32, "MapType": 33, "ParenExpr": 34, "RangeStmt": 35,
	"ReturnStmt": 36, "SelectStmt": 37, "SelectorExpr": 38,
	"SendStmt": 39, "SliceExpr": 40, "StarExpr": 41, "StructType": 42,
	"SwitchStmt": 43, "TypeAssertExpr": 44, "TypeSpec": 45,
	"TypeSwitchStmt": 46, "UnaryExpr": 47, "ValueSpec": 48,
}

func parseSource(path string) (*sourceFile, []syntaxNode, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, nil, err
	}
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, path, data, 0)
	if err != nil {
		return nil, nil, err
	}
	src := &sourceFile{name: path, data: data, lines: []int{0}}
	for i, b := range data {
		if b == '\n' {
			src.lines = append(src.lines, i+1)
		}
	}
	var nodes []syntaxNode
	var visit func(ast.Node)
	visit = func(n ast.Node) {
		if n == nil || reflect.ValueOf(n).IsNil() {
			return
		}
		if decl, ok := n.(*ast.GenDecl); ok && decl.Tok == token.IMPORT {
			return
		}
		kind := nodeKinds[reflect.TypeOf(n).Elem().Name()]
		i := len(nodes)
		nodes = append(nodes, syntaxNode{
			kind: kind, begin: fset.Position(n.Pos()).Offset,
			end: fset.Position(n.End()).Offset, source: src,
		})
		switch x := n.(type) {
		case *ast.File:
			for _, d := range x.Decls {
				visit(d)
			}
		case *ast.AssignStmt:
			for _, e := range x.Rhs {
				visit(e)
			}
			for _, e := range x.Lhs {
				visit(e)
			}
		case *ast.Field:
			for _, id := range x.Names {
				visit(id)
			}
			visit(x.Type)
		case *ast.FuncType:
			visit(x.Params)
			visit(x.Results)
		case *ast.TypeSpec:
			visit(x.Name)
			visit(x.Type)
		default:
			if kind != 0 {
				root := true
				ast.Inspect(n, func(child ast.Node) bool {
					if root {
						root = false
						return true
					}
					if child != nil {
						visit(child)
					}
					return false
				})
			}
		}
		nodes[i].size = len(nodes) - i
	}
	visit(file)
	return src, nodes, nil
}
EOF
cat > clones.go <<'EOF'
package main

import (
	"crypto/sha1"
	"sort"
)

type fragment struct {
	source     *sourceFile
	begin, end int
	first, last int
}

type cloneGroup struct {
	hash      string
	fragments []fragment
}

type fragmentKey struct {
	file       string
	begin, end int
}

// Prefix doubling builds the suffix order without materializing the suffixes.
func suffixOrder(data []syntaxNode) []int {
	n := len(data)
	sa := make([]int, n)
	rank := make([]int, n)
	work := make([]int, n)
	for i, node := range data {
		sa[i] = i
		rank[i] = node.kind
	}
	for width := 1; width < n; width *= 2 {
		second := func(i int) int {
			if i+width >= n {
				return -1
			}
			return rank[i+width]
		}
		sort.Slice(sa, func(i, j int) bool {
			a, b := sa[i], sa[j]
			if rank[a] != rank[b] {
				return rank[a] < rank[b]
			}
			return second(a) < second(b)
		})
		classes := 0
		work[sa[0]] = 0
		for i := 1; i < n; i++ {
			a, b := sa[i-1], sa[i]
			if rank[a] != rank[b] || second(a) != second(b) {
				classes++
			}
			work[b] = classes
		}
		rank, work = work, rank
		if classes == n-1 {
			break
		}
	}
	return sa
}

func commonPrefixes(data []syntaxNode, sa []int) []int {
	rank := make([]int, len(sa))
	lcp := make([]int, len(sa))
	for i, p := range sa {
		rank[p] = i
	}
	length := 0
	for i := range data {
		r := rank[i]
		if r == 0 {
			length = 0
			continue
		}
		j := sa[r-1]
		for i+length < len(data) && j+length < len(data) && data[i+length].kind == data[j+length].kind {
			length++
		}
		lcp[r] = length
		if length > 0 {
			length--
		}
	}
	return lcp
}

// The final uninterrupted run of complete subtrees is the usable part of a
// repeated preorder interval. A small or truncated intervening node breaks it.
func syntaxUnits(data []syntaxNode, start, length, threshold int) []int {
	var units []int
	end := start + length
	for i := start; i < end; {
		n := data[i]
		if n.source != nil && n.size >= threshold && i+n.size <= end {
			if len(units) != 0 {
				last := units[len(units)-1]
				if last+data[last].size != i {
					units = units[:0]
				}
			}
			units = append(units, i-start)
			// Offsets in the result are relative to the occurrence.
			i += n.size
		} else {
			i++
		}
	}
	return units
}

func periodic(data []syntaxNode, start, length int) bool {
	var boundaries []int
	end := 0
	for end < length && end+data[start+end].size <= length {
		end += data[start+end].size
		boundaries = append(boundaries, end)
	}
	for _, period := range boundaries {
		if period*2 > end {
			break
		}
		if end%period != 0 {
			continue
		}
		equal := true
		for i := period; i < end; i++ {
			if data[start+i].kind != data[start+i%period].kind {
				equal = false
				break
			}
		}
		if equal {
			return true
		}
	}
	return false
}

func equalOffsets(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func findClones(data []syntaxNode, threshold int) []cloneGroup {
	if len(data) < 2 {
		return nil
	}
	sa := suffixOrder(data)
	lcp := commonPrefixes(data, sa)
	groups := make(map[string]*cloneGroup)
	seen := make(map[string]map[fragmentKey]bool)
	addRepeat := func(length, left, right int) {
		if length < threshold || right-left < 2 {
			return
		}
		occ := sa[left:right]
		first := occ[0]
		prev := -1
		if first > 0 {
			prev = data[first-1].kind
		}
		leftDiverse := false
		for _, p := range occ {
			v := -1
			if p > 0 {
				v = data[p-1].kind
			}
			if v != prev {
				leftDiverse = true
			}
			if p < first {
				first = p
			}
		}
		if !leftDiverse {
			return
		}
		allPeriodic := true
		for _, p := range occ {
			if !periodic(data, p, length) {
				allPeriodic = false
				break
			}
		}
		if allPeriodic {
			return
		}
		units := syntaxUnits(data, first, length, threshold)
		if len(units) == 0 {
			return
		}
		rootMismatch := false
		for _, p := range occ {
			if data[p].size != data[first].size {
				rootMismatch = true
				break
			}
		}
		for _, p := range occ {
			if rootMismatch && !equalOffsets(units, syntaxUnits(data, p, length, threshold)) {
				return
			}
			for _, offset := range units {
				if data[p+offset].size != data[first+offset].size {
					return
				}
			}
		}
		lo := units[0]
		last := units[len(units)-1]
		stop := last + data[first+last].size - 1
		keyData := make([]byte, stop-lo)
		for i := range keyData {
			keyData[i] = byte(data[first+lo+i].kind)
		}
		sum := sha1.Sum(keyData)
		key := string(sum[:])
		group := groups[key]
		if group == nil {
			group = &cloneGroup{hash: key}
			groups[key] = group
			seen[key] = make(map[fragmentKey]bool)
		}
		for _, p := range occ {
			a, b := data[p+lo], data[p+last]
			if a.source == nil || b.source == nil || a.source != b.source {
				continue
			}
			id := fragmentKey{a.source.name, a.begin, b.end}
			if seen[key][id] {
				continue
			}
			seen[key][id] = true
			f := fragment{source: a.source, begin: a.begin, end: b.end, last: a.source.lineAt(b.end-1)}
			if a.begin < b.end {
				f.first = a.source.lineAt(a.begin)
			}
			group.fragments = append(group.fragments, f)
		}
	}

	type interval struct{ length, left int }
	var stack []interval
	for i := 1; i <= len(sa); i++ {
		height := 0
		if i < len(sa) {
			height = lcp[i]
		}
		left := i - 1
		for len(stack) > 0 && stack[len(stack)-1].length > height {
			x := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			addRepeat(x.length, x.left, i)
			left = x.left
		}
		if height > 0 && (len(stack) == 0 || stack[len(stack)-1].length < height) {
			stack = append(stack, interval{height, left})
		}
	}
	result := make([]cloneGroup, 0, len(groups))
	for _, g := range groups {
		if len(g.fragments) < 2 {
			continue
		}
		sort.Slice(g.fragments, func(i, j int) bool {
			a, b := g.fragments[i], g.fragments[j]
			if a.source.name != b.source.name {
				return a.source.name < b.source.name
			}
			return a.first < b.first
		})
		result = append(result, *g)
	}
	sort.Slice(result, func(i, j int) bool { return result[i].hash < result[j].hash })
	return result
}
