package main

// File/line comparisons intentionally leave fragments starting on the same
// line unordered. A small-gap partition sort preserves the CLI's tie order.
func sortFragments(f []fragment) {
	less := func(i, j int) bool {
		if f[i].source.name != f[j].source.name {
			return f[i].source.name < f[j].source.name
		}
		return f[i].first < f[j].first
	}
	swap := func(i, j int) { f[i], f[j] = f[j], f[i] }
	median := func(mid, low, high int) {
		if less(mid, low) { swap(mid, low) }
		if less(high, mid) {
			swap(high, mid)
			if less(mid, low) { swap(mid, low) }
		}
	}
	partition := func(low, high int) (int, int) {
		mid := (low + high) / 2
		if high-low > 40 {
			s := (high-low)/8
			median(low,low+s,low+2*s)
			median(mid,mid-s,mid+s)
			median(high-1,high-1-s,high-1-2*s)
		}
		median(low,mid,high-1)
		pivot:=low
		a,c:=low+1,high-1
		for a<c && less(a,pivot) { a++ }
		b:=a
		for {
			for b<c && !less(pivot,b) { b++ }
			for b<c && less(pivot,c-1) { c-- }
			if b>=c { break }
			swap(b,c-1); b++; c--
		}
		protect := high-c < 5
		if !protect && high-c < (high-low)/4 {
			equal:=0
			if !less(pivot,high-1) { swap(c,high-1);c++;equal++ }
			if !less(b-1,pivot) { b--;equal++ }
			if !less(mid,pivot) { swap(mid,b-1);b--;equal++ }
			protect=equal>1
		}
		if protect {
			for {
				for a<b && !less(b-1,pivot) { b-- }
				for a<b && less(a,pivot) { a++ }
				if a>=b { break }
				swap(a,b-1);a++;b--
			}
		}
		swap(pivot,b-1)
		return b-1,c
	}
	var quick func(int,int)
	quick=func(a,b int) {
		for b-a>12 {
			lo,hi:=partition(a,b)
			if lo-a<b-hi { quick(a,lo);a=hi } else { quick(hi,b);b=lo }
		}
		if b-a>1 {
			for i:=a+6;i<b;i++ { if less(i,i-6) { swap(i,i-6) } }
			for i:=a+1;i<b;i++ { for j:=i;j>a && less(j,j-1);j-- { swap(j,j-1) } }
		}
	}
	quick(0,len(f))
}
EOF
