package main

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"unicode/utf8"
)

func fixture(t *testing.T, name, code string) (*sourceFile, []syntaxNode) {
	t.Helper()
	path := filepath.Join(t.TempDir(), name)
	if err := os.WriteFile(path, []byte(code), 0600); err != nil {
		t.Fatal(err)
	}
	source, nodes, err := parseSource(path)
	if err != nil {
		t.Fatal(err)
	}
	source.name = name
	return source, nodes
}

func output(groups []cloneGroup, opts options) string {
	var b bytes.Buffer
	render(&b, groups, opts)
	return b.String()
}

const twoFunctions = `package p

func alpha(x int) int {
    a := x + 1
    b := a * 2
    return b
}

func beta(y int) int {
    c := y + 3
    d := c * 4
    return d
}
`

func TestThresholdsAndNormalization(t *testing.T) {
	_, nodes := fixture(t, "simple.go", twoFunctions)
	for _, test := range []struct{ threshold, count int }{{1, 3}, {5, 2}, {6, 1}, {15, 1}, {23, 1}, {24, 0}} {
		groups := findClones(nodes, test.threshold)
		if len(groups) != test.count {
			t.Errorf("threshold %d: got %d groups, want %d", test.threshold, len(groups), test.count)
		}
	}
	groups := findClones(nodes, 15)
	want := "found 2 clones:\n  simple.go:3,7\n  simple.go:9,13\n\nFound total 1 clone groups.\n"
	if got := output(groups, options{}); got != want {
		t.Fatalf("plain output:\n%s", got)
	}
	want = "simple.go:3-7: duplicate of simple.go:9-13\nsimple.go:9-13: duplicate of simple.go:3-7\n"
	if got := output(groups, options{plumbing: true}); got != want {
		t.Fatalf("plumbing output:\n%s", got)
	}
}

func TestRepeatedUnits(t *testing.T) {
	_, nodes := fixture(t, "pairs.go", `package p
func f() {
 a := 1
 foo()
 b := 2
 bar()
 c := 3
 baz()
}
`)
	groups := findClones(nodes, 3)
	want := "found 3 clones:\n  pairs.go:3,4\n  pairs.go:5,6\n  pairs.go:7,8\n\nFound total 1 clone groups.\n"
	if got := output(groups, options{}); got != want {
		t.Fatalf("periodic sequence output:\n%s", got)
	}
	if got := len(findClones(nodes, 4)); got != 0 {
		t.Errorf("units smaller than threshold: got %d groups", got)
	}
}

func TestTruncatedSubtree(t *testing.T) {
	_, nodes := fixture(t, "prefix.go", `package p
func a() {
 a := 1
 foo(a)
 bar(a)
}
func b() {
 a := 1
 foo(a)
 bar(a)
 return
}
`)
	if got := len(findClones(nodes, 5)); got != 0 {
		t.Errorf("incomplete enclosing function should not be a clone: %d groups", got)
	}
	want := "found 4 clones:\n  prefix.go:4,4\n  prefix.go:5,5\n  prefix.go:9,9\n  prefix.go:10,10\n\nFound total 1 clone groups.\n"
	if got := output(findClones(nodes, 2), options{}); got != want {
		t.Fatalf("complete statement output:\n%s", got)
	}
}

func TestFileNormalization(t *testing.T) {
	_, a := fixture(t, "a.go", "package a\nimport \"one\"\ntype A struct { x int `json:\"x\"` }\n")
	_, b := fixture(t, "b.go", "// comment\npackage b\nimport alias \"two\"\ntype B struct { y int `xml:\"y\"` }\n")
	if len(a) != len(b) {
		t.Fatalf("imports, comments and tags changed node count: %d != %d", len(a), len(b))
	}
	for i := range a {
		if a[i].kind != b[i].kind || a[i].size != b[i].size {
			t.Errorf("node %d differs after normalization", i)
		}
	}
	groups := findClones(append(a, b...), len(a))
	if len(groups) != 1 || len(groups[0].fragments) != 2 {
		t.Fatalf("expected two whole-file clones: %v", groups)
	}
}

func TestIgnoredTypeParameters(t *testing.T) {
	_, nodes := fixture(t, "generic.go", "package p\nfunc F[T any](x T) T {return x}\nfunc G[U any](y U) U {return y}\n")
	if len(findClones(nodes, 13)) != 1 || len(findClones(nodes, 14)) != 0 {
		t.Fatal("type parameters must not enter the normalized node sequence")
	}
}

func TestHTMLOrdering(t *testing.T) {
	_, nodes := fixture(t, "three.go", "package p\nfunc a() { f(1) }\nfunc b() { g(2) }\nfunc c() { h(3) }\n")
	want := htmlHeader + `<h1>#1 found 6 clones</h1>
<h2>three.go:2</h2>
<pre>           f</pre>
<h2>three.go:2</h2>
<pre>     a</pre>
<h2>three.go:3</h2>
<pre>           g</pre>
<h2>three.go:3</h2>
<pre>     b</pre>
<h2>three.go:4</h2>
<pre>           h</pre>
<h2>three.go:4</h2>
<pre>     c</pre>
<h1>#2 found 3 clones</h1>
<h2>three.go:2</h2>
<pre>func a() { f(1) }</pre>
<h2>three.go:3</h2>
<pre>func b() { g(2) }</pre>
<h2>three.go:4</h2>
<pre>func c() { h(3) }</pre>
`
	if got := output(findClones(nodes, 1), options{html: true}); got != want {
		t.Fatalf("HTML ordering:\n%s", got)
	}
}

func TestHTMLWhitespaceAndEscaping(t *testing.T) {
	text := "func α(世界 int) int { return 世界 }\n"
	start := strings.LastIndex(text, "世界")
	f := fragment{source: &sourceFile{data: []byte(text)}, begin: start, end: start + len("世界")}
	want := strings.Repeat(" ", utf8.RuneCountInString(text[:start])) + "世界"
	if got := codeFragment(f); got != want {
		t.Fatalf("Unicode padding: got %q, want %q", got, want)
	}
	for _, test := range []struct{ text, want string }{
		{"\t\tif x {\n\tf()\ng()\n}", "\t\tif x {\n\tf()\ng()\n}"},
		{"\t\tif x {\n\t\t\tf()\n  \n\t\t}", "if x {\n\tf()\n  \n}"},
	} {
		f = fragment{source: &sourceFile{data: []byte(test.text)}, begin: 2, end: len(test.text)}
		if got := codeFragment(f); got != test.want {
			t.Fatalf("indentation: got %q, want %q", got, test.want)
		}
	}
	f = fragment{source: &sourceFile{data: []byte("\"<>&'\"")}, end: 6}
	if got := codeFragment(f); got != "&#34;&lt;&gt;&amp;&#39;&#34;" {
		t.Fatalf("HTML escaping: %q", got)
	}
}

func TestEmptyOutput(t *testing.T) {
	if got := output(nil, options{}); got != "\nFound total 0 clone groups.\n" {
		t.Fatal(got)
	}
	if got := output(nil, options{html: true}); got != htmlHeader {
		t.Fatal(got)
	}
	if got := output(nil, options{plumbing: true}); got != "" {
		t.Fatal(got)
	}
}
EOF
